class Solution {
public:
    int len(int x) {
        int d = 1;
        while (abs(x) >= 10) { x /= 10; d++; }
        return d;
    }
    vector<int> findColumnWidth(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<int> ans(n);
        for (int c = 0; c < n; c++) {
            int w = 0;
            for (int r = 0; r < m; r++) {
                int v = grid[r][c], l = len(v) + (v < 0 ? 1 : 0);
                w = max(w, l);
            }
            ans[c] = w;
        }
        return ans;
    }
};

