var findColumnWidth = function(grid) {
    const L = x => (x === 0 ? 1 : Math.floor(Math.log10(Math.abs(x))) + 1) + (x < 0 ? 1 : 0);
    const m = grid.length, n = grid[0].length, ans = [];
    for (let c = 0; c < n; c++) {
        let w = 0;
        for (let r = 0; r < m; r++) w = Math.max(w, L(grid[r][c]));
